#ifndef TX_THREAD_SECURE_STACK_REGISTERS_H
#define TX_THREAD_SECURE_STACK_REGISTERS_H

/* MISRA C:2023 Rule 1.2 and Directive 4.3. GNU assembly accesses the
   Cortex-M55 special registers.  */
#define TX_SECURE_REGISTER_READ(reg, value) \
    __asm__ volatile("MRS     %0, " #reg : "=r" (value))
#define TX_SECURE_REGISTER_WRITE(reg, value) \
    __asm__ volatile("MSR     " #reg ", %0" :: "r" (value))

/* Keep both active stack registers clear before the allocator can reuse the stack.  */
#define TX_SECURE_STACK_CLEAR_BEFORE_FREE() \
    __asm__ volatile("MSR     PSPLIM, %0\n\tMSR     PSP, %0" :: "r" (0UL) : "memory")

#endif
